package org.brightstats.stats;
import java.util.*;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.special.Gamma;

/** Joint control-coefficient Wald tests using a shared case-bootstrap covariance. */
public final class CopulaWald {
    private CopulaWald(){}
    public record Result(String scope,int parameters,int successfulDraws,int covarianceRank,Double statistic,Double pValue,String interpretation){}
    static final class Accumulator {
        private final List<Bootstrap.Parameter> parameters;private final List<Integer> selected=new ArrayList<>();private final double[] point;private final List<double[]> draws=new ArrayList<>();private final String disabled;private final List<String> names;
        Accumulator(AdjustedCopula.Fit fit,int attempts){parameters=AdjustedCopula.parameters(fit);point=AdjustedCopula.values(fit);names=fit.model().names();for(int i=0;i<parameters.size();i++)if(parameters.get(i).family().equals("Adjusted copula control"))selected.add(i);disabled=(long)selected.size()*attempts>1000000?"Joint covariance storage would exceed one million coefficient values; individual bootstrap inference is retained.":null;}
        void accept(double[] values){if(disabled!=null)return;double[] controls=new double[selected.size()];for(int i=0;i<controls.length;i++)controls[i]=values[selected.get(i)];draws.add(controls);}
        List<Result> finish(int successful){List<Result> out=new ArrayList<>();Set<Integer> targets=new LinkedHashSet<>();for(int index:selected)targets.add(parameters.get(index).target());for(int target:targets){List<Integer> subset=new ArrayList<>();for(int j=0;j<selected.size();j++)if(parameters.get(selected.get(j)).target()==target)subset.add(j);out.add(test("Controls for "+names.get(target),subset,successful));}if(targets.size()>1)out.add(test("All selected controls",java.util.stream.IntStream.range(0,selected.size()).boxed().toList(),successful));return List.copyOf(out);}
        private Result test(String scope,List<Integer> subset,int successful){int p=subset.size();String note="Covariance is estimated from shared successful case-bootstrap draws; the null sets all listed control coefficients to zero. The P-value uses an asymptotic chi-square reference, not an empirical bootstrap-calibrated null distribution. A non-significant result does not prove exogeneity.";if(disabled!=null)return new Result(scope,p,successful,0,null,null,disabled);if(draws.size()!=successful)throw new IllegalStateException("Wald draw accounting differs from accepted bootstrap fits.");if(p>256||successful<=p)return new Result(scope,p,successful,0,null,null,"Joint test unavailable: require more successful draws than control coefficients and at most 256 joint targets. "+note);double[] mean=new double[p],sd=new double[p];for(var row:draws)for(int j=0;j<p;j++)mean[j]+=row[subset.get(j)]/successful;for(var row:draws)for(int j=0;j<p;j++){double value=row[subset.get(j)]-mean[j];sd[j]+=value*value/(successful-1);}for(int j=0;j<p;j++){sd[j]=Math.sqrt(sd[j]);if(!(sd[j]>0)||!Double.isFinite(sd[j]))return new Result(scope,p,successful,0,null,null,"Joint test unavailable: at least one control has zero/nonfinite bootstrap variance. "+note);}double[][] correlation=new double[p][p];for(var row:draws)for(int a=0;a<p;a++)for(int b=0;b<p;b++)correlation[a][b]+=(row[subset.get(a)]-mean[a])/sd[a]*(row[subset.get(b)]-mean[b])/sd[b]/(successful-1);var svd=new SingularValueDecomposition(new Array2DRowRealMatrix(correlation,false));int rank=svd.getRank();if(rank!=p||!Double.isFinite(svd.getConditionNumber())||svd.getConditionNumber()>1e10)return new Result(scope,p,successful,rank,null,null,"Joint test unavailable: bootstrap control covariance is rank deficient or ill-conditioned. "+note);double[] standardized=new double[p];for(int j=0;j<p;j++)standardized[j]=point[selected.get(subset.get(j))]/sd[j];var vector=new ArrayRealVector(standardized,false);double statistic=vector.dotProduct(svd.getSolver().solve(vector));if(!Double.isFinite(statistic)||statistic<0)return new Result(scope,p,successful,rank,null,null,"Joint test unavailable: Wald statistic exceeds finite numeric limits. "+note);return new Result(scope,p,successful,rank,statistic,Gamma.regularizedGammaQ(p/2.0,statistic/2),note);}
    }
}
